(3886606, 547823, 66353, '<td valign="top">I have no idea if this fits the challenge (I''m not sure I understand what the challenge is about) - but I like your picture (whatever it is)</td>', 'I have no idea if this fits the challenge (I''m not sure I understand what the challenge is about) - but I like your picture (whatever it is)', '2007-07-09 18:04:18.000000', NULL, 1),
(3886617, 549895, 66353, '<td valign="top">It really could use some contrast</td>', 'It really could use some contrast', '2007-07-09 18:06:23.000000', NULL, 1),
