(3905385, 548063, 66085, '<td valign="top">one word... wow</td>', 'one word... wow', '2007-07-15 16:41:23.000000', NULL, 1),
(3905554, 549005, 15711, '<td valign="top">Love the sky!! Nice composition. The sun is gilding the metal structures.</td>', 'Love the sky!! Nice composition. The sun is gilding the metal structures.', '2007-07-15 18:14:42.000000', NULL, 1),
(3905555, 551196, 15711, '<td valign="top">I love the dreaminess.  Sometimes a duotone that''s a different color looks funky but this is really perfectly suited. I love the clouds. Nice balance of trees with the hint of the one on the left. 7</td>', 'I love the dreaminess.  Sometimes a duotone that''s a different color looks funky but this is really perfectly suited. I love the clouds. Nice balance of trees with the hint of the one on the left. 7', '2007-07-15 18:15:36.000000', NULL, 1),
(3905561, 550960, 15711, '<td valign="top">This is really beautiful. I''m trying to figure out what those plastic things are. Is it like greenhouses to protect the greenery beneath?  The tree is perfectly placed and the blue sky is rich and pleasing.</td>', 'This is really beautiful. I''m trying to figure out what those plastic things are. Is it like greenhouses to protect the greenery beneath?  The tree is perfectly placed and the blue sky is rich and pleasing.', '2007-07-15 18:17:18.000000', NULL, 1),
(3905563, 550314, 15711, '<td valign="top">Great idea. I love how his right hand becomes lost in the sun''s light.</td>', 'Great idea. I love how his right hand becomes lost in the sun''s light.', '2007-07-15 18:17:50.000000', NULL, 1),
(3905564, 548289, 15711, '<td valign="top">NOt sure if this is a true dichotomy, but I''m just voting on the photo itself.  The subject of the challenge is so esoteric, that seeing a beautifully executed shot such as this - I''m giving it a high score because it''s beautiful, well focused and the bokeh is superb.</td>', 'NOt sure if this is a true dichotomy, but I''m just voting on the photo itself.  The subject of the challenge is so esoteric, that seeing a beautifully executed shot such as this - I''m giving it a high score because it''s beautiful, well focused and the bokeh is superb.', '2007-07-15 18:17:53.000000', NULL, 1),
